[90004] = {"重生币","重生币通过克罗米将您重置为1级和重生日常任务获得。这些代币可用于从克罗米处购买独特幻化和传家宝。","Limitzero"},
[97304] = {"重生宝箱","经典旧世\n服务器绑定\n需要60级\n","Limitzero"},
[97397] = {"赛季积分","赛季积分是赛季专属货币。需要在DP商城、市场货币商人或者拍卖行购买[Seasonal Achievements Unlock]解锁。赛季积分可以解锁虚荣物品中的幻化奖励，解锁后也可在主服务器（52区）获得！","Limitzero"},
[97398] = {"赛季成就解锁","cffff1100赛季服绝版\n拾取绑定\n此道具将解锁你的赛季成就收集。此允许你在赛季获取赛季点数。这些点数可以花费在解锁绝版装饰。","Limitzero"},
[97399] = {"金色暗月奖券","从赛拉斯·暗月提供的金色密封卡包中获得，这些奖券可以在赛拉斯处兑换特定技能卡和其他奢华奖励！","Limitzero"},
[97399] = {"金色暗月奖券","从赛拉斯·暗月提供的金色密封卡包中获得，这些票可以在赛拉斯兑换特定技能卡和其他奢华奖励！","Limitzero"},
[97730] = {"世界铸造钥匙碎片","使用： 将5块世界铸造钥匙碎片转化为世界铸造钥匙。","Limitzero"},
